<script setup lang="ts">import {ref,onMounted} from 'vue';import {datasets} from '../stores/datasets';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {fixed,pct} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),text=ref(''),description=ref(''),selected=ref('demo-dataset');const {error,busy,act}=useTask();onMounted(datasets.load);async function file(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f)text.value=await f.text()}function submit(){act(async()=>{await datasets.create({name:name.value,csv_text:text.value,description:description.value});name.value='';text.value=''})}</script><template><PageHeading index="01 / 原浆检测" title="每种原浆，都有自己的价格与边界。" note="成本单位元/吨；强度为模拟指数0–100，白度0–100%，回收纤维率0–1。中心±扰动宽度必须落在物理范围内。"/><div class="two-col"><section><Notice :message="datasets.error.value"/><article v-for="r in datasets.items.value" :key="r.id" class="dataset-row"><button class="record-open" @click="selected=selected===r.id?'':r.id"><h3>{{r.name}}</h3><p>{{r.materials.length}}种 · {{r.description}}</p><span>展开检测与供给记录 ↗</span></button><div v-if="selected===r.id" class="table-wrap"><table><thead><tr><th>原浆</th><th>成本±幅度</th><th>强度±幅度</th><th>白度±幅度</th><th>回收率±幅度</th><th>供给比例</th></tr></thead><tbody><tr v-for="m in r.materials" :key="m.material_id"><td>{{m.name}}</td><td>{{m.cost}}±{{m.cost_width}}</td><td>{{m.strength}}±{{m.strength_width}}</td><td>{{m.whiteness}}±{{m.whiteness_width}}</td><td>{{pct(m.recycled)}}±{{pct(m.recycled_width)}}</td><td>{{pct(m.min_share)}}—{{pct(m.max_share)}}</td></tr></tbody></table></div></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>导入原浆批次</h2><label>批次名称<input v-model="name" required minlength="2"></label><label>CSV文件<input type="file" accept=".csv" @change="file"></label><label>原浆CSV<textarea v-model="text" rows="9" required placeholder="material_id,name,cost,min_share,max_share,strength,whiteness,recycled,strength_width,whiteness_width,recycled_width,cost_width"></textarea></label><label>检测/报价说明<input v-model="description"></label><Notice :message="error"/><button :disabled="busy">校验并导入原浆</button></form><aside v-else class="margin-note">只读账号可以核查原浆参数。导入需要分析师权限。</aside></div></template>
